CREATE SCHEMA auth;
CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql STABLE AS $$SELECT current_setting('request.jwt.claim.role',true)$$;
GRANT USAGE ON SCHEMA auth TO anon,authenticated,service_role;
CREATE SCHEMA rating_validation_b3b;
REVOKE ALL ON SCHEMA rating_validation_b3b FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE rating_validation_b3b.protocol(singleton boolean PRIMARY KEY CHECK(singleton),manifest jsonb NOT NULL,manifest_hash text NOT NULL,worker_hash text NOT NULL);
CREATE TABLE rating_validation_b3b.environment_protocol(LIKE rating_validation_b3b.protocol INCLUDING ALL,baseline_context jsonb NOT NULL);
CREATE TABLE rating_validation_b3b.intents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),roster jsonb NOT NULL,match_type text NOT NULL DEFAULT 'CLUB_RATED',score_mode text NOT NULL DEFAULT 'POINTS');
CREATE TABLE rating_validation_b3b.boundaries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intent_id uuid NOT NULL REFERENCES rating_validation_b3b.intents,captured_at timestamptz NOT NULL,source_text text NOT NULL,fingerprint text NOT NULL,source_hash text NOT NULL,roster_hash text NOT NULL);
CREATE TABLE rating_validation_b3b.boundary_context(boundary_id uuid PRIMARY KEY REFERENCES rating_validation_b3b.boundaries,baseline_context jsonb NOT NULL);
CREATE TABLE rating_validation_b3b.seals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intent_id uuid UNIQUE NOT NULL REFERENCES rating_validation_b3b.intents,boundary_id uuid UNIQUE NOT NULL REFERENCES rating_validation_b3b.boundaries,sealed_at timestamptz NOT NULL DEFAULT clock_timestamp(),canonical_payload bytea NOT NULL,payload jsonb NOT NULL,payload_hash text GENERATED ALWAYS AS(encode(sha256(canonical_payload),'hex')) STORED,CHECK(convert_from(canonical_payload,'UTF8')::jsonb=payload));
CREATE TABLE rating_validation_b3b.requests(intent_id uuid NOT NULL REFERENCES rating_validation_b3b.intents);
CREATE TABLE rating_validation_b3b.events(intent_id uuid NOT NULL REFERENCES rating_validation_b3b.intents,kind text NOT NULL);
CREATE TABLE rating_validation_b3b.fixture_source(value jsonb NOT NULL);
INSERT INTO rating_validation_b3b.fixture_source VALUES('{"captured_at":"2026-10-30T00:00:00+00:00","fixture":"SYNTHETIC ONLY"}');
CREATE FUNCTION rating_validation_b3b.source() RETURNS jsonb LANGUAGE sql AS $$SELECT value FROM rating_validation_b3b.fixture_source$$;
CREATE FUNCTION rating_validation_b3b.hash_json(v jsonb) RETURNS text LANGUAGE sql IMMUTABLE AS $$SELECT encode(sha256(convert_to(v::text,'UTF8')),'hex')$$;
CREATE FUNCTION rating_validation_b3b.fingerprint(v jsonb) RETURNS text LANGUAGE sql IMMUTABLE AS $$SELECT rating_validation_b3b.hash_json(v)$$;
CREATE FUNCTION rating_validation_b3b.worker() RETURNS void LANGUAGE plpgsql AS $$BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'WORKER_REQUIRED'; END IF; END$$;
CREATE FUNCTION rating_validation_b3b.eligible(i rating_validation_b3b.intents) RETURNS void LANGUAGE plpgsql AS $$BEGIN RETURN; END$$;
CREATE FUNCTION rating_validation_b3b.terminal(i uuid) RETURNS boolean LANGUAGE sql AS $$SELECT false$$;
CREATE FUNCTION rating_validation_b3b.immutable() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'IMMUTABLE'; END$$;
CREATE TRIGGER immutable_rows BEFORE UPDATE OR DELETE ON rating_validation_b3b.seals FOR EACH ROW EXECUTE FUNCTION rating_validation_b3b.immutable();
CREATE TRIGGER immutable_truncate BEFORE TRUNCATE ON rating_validation_b3b.seals FOR EACH STATEMENT EXECUTE FUNCTION rating_validation_b3b.immutable();
CREATE TABLE public.matches(id uuid PRIMARY KEY);
CREATE TABLE public.rating_events(id uuid PRIMARY KEY);
